DECLARE @output VARCHAR(MAX)
set @output ='@{activity('Get_ListOfFiles_Since_LUD').output.childitems}';;

WITH CTE AS (
    SELECT filename AS fileName
    FROM OPENJSON(@output)
    WITH (filename VARCHAR(100) '$.name')
)
SELECT FileName, CONVERT(DATE,LEFT(RIGHT(FileName, 12),8)) AS DatePart
FROM CTE

ORDER BY CONVERT(DATE,LEFT(RIGHT(FileName, 12),8));

